  const [orderDate, setOrderDate] = useState(() => formatDateISO(new Date()));
  const [searchTerm, setSearchTerm] = useState("");
  // Removido: observações gerais

  // Estados para entrada de produção
  const [productionEntries, setProductionEntries] = useState<ProductionEntry[]>([]);

  // Estados para modal de adição de produto
