  const [whatsappMessage, setWhatsappMessage] = useState("");
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [aiItems, setAiItems] = useState<Array<{ name: string; quantity: number }>>([]);
  const [dbProducts, setDbProducts] = useState<Array<{ id: number; nome: string }>>([]);
  const [allProducts, setAllProducts] = useState<string[]>(DAILY_PRODUCTION_PRODUCTS); // Lista combinada de produtos
  const [matchedItems, setMatchedItems] = useState<Array<{
    originalName: string;
    quantity: number;
    matchedName?: string;
    matchedId?: number;
    selected?: boolean;
    suggestions?: Array<{ id: number; nome: string }>;
  }>>([]);

  // Estados para modal de registro de novo produto
  const [isNewProductModalOpen, setIsNewProductModalOpen] = useState(false);
  const [newProductName, setNewProductName] = useState("");
  const [isCreatingProduct, setIsCreatingProduct] = useState(false);

  // Estados para voz
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Estados para histórico e analytics
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [analytics, setAnalytics] = useState<AnalyticsData>({
    totalProduction: 0,
    momGrowth: 0,
    efficiency: 0,
    activeDays: 0,
    topProducts: [],
    products: [],
    dailyTrend: [],
    monthlyTrend: [],
    hourlyDistribution: [],
    dayOfWeekAnalysis: [],
    rawEntries: [],
    previousRawEntries: []
  });
  const [selectedAnalyticsProduct, setSelectedAnalyticsProduct] = useState<string | null>(null);
  const [isProductDetailModalOpen, setIsProductDetailModalOpen] = useState(false);
  const [analyticsProductSearch, setAnalyticsProductSearch] = useState("");
  const [historyFilter, setHistoryFilter] = useState("");
  const [dateRange, setDateRange] = useState({
    start: formatDateISO(new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)),
    end: formatDateISO(new Date())
  });

  // Filtros próprios do Analytics
  const [analyticsPreset, setAnalyticsPreset] = useState<"7d" | "30d" | "90d" | "custom">("30d");
  const [analyticsDateRange, setAnalyticsDateRange] = useState({
    start: formatDateISO(new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)),
    end: formatDateISO(new Date()),
  });
  const [analyticsViewMode, setAnalyticsViewMode] = useState<"daily" | "monthly">("monthly");

  // Gestão da lista de produção (adicionados e exclusões dos padrões)
  const [dailyAdditions, setDailyAdditions] = useState<Array<{ id: number; name: string; active: boolean }>>([]);
  const [dailyExclusions, setDailyExclusions] = useState<string[]>([]);
  const [isManageModalOpen, setIsManageModalOpen] = useState(false);

  // NOVOS ESTADOS PARA UX MELHORADA
  const [isProductListExpanded, setIsProductListExpanded] = useState(false);
  const [isDateModalOpen, setIsDateModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(() => formatDateISO(new Date()));
  const [isDeleteMode, setIsDeleteMode] = useState(false);
  const [selectedForDeletion, setSelectedForDeletion] = useState<string[]>([]);
  const [manageSearchTerm, setManageSearchTerm] = useState("");
  const [isDeletingProducts, setIsDeletingProducts] = useState(false);

  // Estados para edição de produção
  const [isEditMode, setIsEditMode] = useState(false);
  const [editingEntry, setEditingEntry] = useState<HistoryEntry | null>(null);
  const [editProduct, setEditProduct] = useState("");
  const [editQuantity, setEditQuantity] = useState("");
  const [editDate, setEditDate] = useState("");

  const applyAnalyticsPreset = (preset: "7d" | "30d" | "90d") => {
    const days = preset === "7d" ? 7 : preset === "30d" ? 30 : 90;
    setAnalyticsPreset(preset);
    setAnalyticsDateRange({
      start: formatDateISO(new Date(Date.now() - days * 24 * 60 * 60 * 1000)),
      end: formatDateISO(new Date()),
    });
  };

  // Produtos filtrados para busca
  const filteredProducts = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return allProducts;
    return allProducts.filter(product =>
      product.toLowerCase().includes(term)
    );
  }, [searchTerm, allProducts]);

  const manageFilteredProducts = useMemo(() => {
    const term = manageSearchTerm.toLowerCase().trim();
    if (!term) return allProducts;
    return allProducts.filter(name => name.toLowerCase().includes(term));
  }, [manageSearchTerm, allProducts]);

  // Produtos disponíveis (que ainda não foram adicionados)
  const availableProducts = useMemo(() => {
    const addedProducts = productionEntries.map(entry => entry.product_name);
    return filteredProducts.filter(product => !addedProducts.includes(product));
  }, [filteredProducts, productionEntries]);

  // Categorias filtradas para comanda de pedido
  const filteredOrderCategories = useMemo(() => {
    const term = orderSearch.toLowerCase().trim();
    if (!term) return ORDER_PRODUCTS_BY_CATEGORY;
    return ORDER_PRODUCTS_BY_CATEGORY
      .map(cat => ({ ...cat, products: cat.products.filter(p => p.toLowerCase().includes(term)) }))
      .filter(cat => cat.products.length > 0);
  }, [orderSearch]);

  const addOrderItem = (product: string) => {
    setOrderItems(prev => prev.find(i => i.product === product) ? prev : [...prev, { product, qty: 1 }]);
  };
  const adjustOrderQty = (product: string, delta: number) => {
    setOrderItems(prev => prev.map(i => i.product === product ? { ...i, qty: Math.max(1, i.qty + delta) } : i));
  };
  const removeOrderItem = (product: string) => {
    setOrderItems(prev => prev.filter(i => i.product !== product));
  };

  const printOrderPedido = () => {
    if (orderItems.length === 0) return;
    const dateFmt = parseISODateLocal(orderDate).toLocaleDateString("pt-BR");
    const rows = orderItems.map(item => `
      <tr>
        <td class="produto">${item.product}</td>
        <td class="qty">${item.qty}</td>
        <td class="feito"></td>
      </tr>`).join("");
    const html = `<html>
<head>
  <meta charset="utf-8"/>
  <title>Comanda de Pedido - Momma</title>
  <style>
    @page { size: 80mm auto; margin: 0; }
    * { box-sizing: border-box; }
    body { font-family: 'Courier New', Courier, monospace; width: 70mm; margin: 0 auto; padding: 3mm 1mm; color: #000; background: #fff; }
    .header { text-align: center; margin-bottom: 8px; border-bottom: 2px dashed #000; padding-bottom: 8px; }
    .brand { font-size: 20px; font-weight: 900; text-transform: uppercase; letter-spacing: 4px; }
    .title { font-size: 10px; font-weight: bold; margin-top: 4px; text-transform: uppercase; letter-spacing: 2px; }
    .date { font-size: 10px; margin-top: 3px; }
    table { width: 100%; border-collapse: collapse; margin-top: 6px; }
    thead th { font-size: 9px; font-weight: 900; text-transform: uppercase; border-bottom: 2px solid #000; padding: 3px 2px; }
    th:first-child, td:first-child { text-align: left; }
    th:nth-child(2), td:nth-child(2) { text-align: center; }
    th:last-child, td:last-child { text-align: center; }
    td { font-size: 11px; padding: 4px 2px; border-bottom: 1px dotted #bbb; }
    .produto { width: 54%; font-weight: bold; }
    .qty { width: 18%; font-weight: 900; font-size: 13px; }
    .feito { width: 28%; border-bottom: 1px solid #000 !important; height: 20px; }
    .footer { margin-top: 14px; border-top: 2px dashed #000; padding-top: 10px; }
    .total { font-size: 10px; text-align: center; margin-bottom: 10px; }
    .sign-label { font-size: 9px; text-align: center; margin-bottom: 2px; }
    .sign-line { border-bottom: 1px solid #000; width: 50mm; margin: 0 auto; height: 16px; }
  </style>
</head>
<body>
  <div class="header">
    <div class="brand">MOMMA</div>
    <div class="title">Comanda de Pedido</div>
    <div class="date">Data: <b>${dateFmt}</b></div>
  </div>
  <table>
    <thead><tr><th class="produto">Produto</th><th>Pedido</th><th>Feito</th></tr></thead>
    <tbody>${rows}</tbody>
  </table>
  <div class="footer">
    <div class="total">${orderItems.length} ${orderItems.length === 1 ? "item" : "itens"} | Total: ${orderItems.reduce((s, i) => s + i.qty, 0)} un.</div>
    <div class="sign-label">Responsavel</div>
    <div class="sign-line"></div>
  </div>
</body>
</html>`;
    printHTML(html, { title: 'Comanda de Pedido' });
  };

  // Carregar dados quando mudar de tab
  useEffect(() => {
    if (activeTab === "history") {
      loadHistory();
    } else if (activeTab === "analytics") {
      loadAnalytics();
    }
  }, [activeTab]);

  // Carregar lista de produção: padrões + adicionados − excluídos
  useEffect(() => {
    const reloadDailyList = async () => {
      const { data: additionsData, error: additionsError } = await supabase
        .from('daily_production_products')
        .select('id, name, active');
      if (additionsError) {
        handleError(additionsError, { domain: 'producao', operation: 'loadDailyProductionProducts', showToast: false });
        setDailyAdditions([]);
      } else {
        setDailyAdditions(additionsData || []);
      }

      const { data: exclusionsData, error: exclusionsError } = await supabase
        .from('daily_production_exclusions')
        .select('name');
      if (exclusionsError) {
        handleError(exclusionsError, { domain: 'producao', operation: 'loadDailyProductionExclusions', showToast: false });
        setDailyExclusions([]);
      } else {
        setDailyExclusions((exclusionsData || []).map((e: any) => e.name));
      }

      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
      const includedDefaults = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
      const finalList = Array.from(new Set([...activeAdditions, ...includedDefaults]));
      setAllProducts(finalList);
    };

    reloadDailyList();
  }, []);

  // Funções para entrada de produção
  const openAddModal = (productName?: string) => {
    setSelectedProduct(productName || "");
    setNewQuantity("");
    setIsAddModalOpen(true);
  };

  const closeAddModal = () => {
    setIsAddModalOpen(false);
    setSelectedProduct("");
    setNewQuantity("");
  };

  // Importação via WhatsApp (IA)
  const openImportModal = async () => {
    setWhatsappMessage("");
    setAiItems([]);
    setMatchedItems([]);
    setIsImportModalOpen(true);
    // Importação via WhatsApp: usar padrões incluídos + adicionados ativos
    try {
      const { data: additionsData } = await supabase
        .from('daily_production_products')
        .select('id, name, active');

      const { data: exclusionsData } = await supabase
        .from('daily_production_exclusions')
        .select('name');

      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS
        .filter(p => !exclusions.includes(p.toLowerCase()))
        .map((product, index) => ({ id: -(index + 1), nome: product }));

      const activeAdditions = (additionsData || [])
        .filter((a: any) => a.active)
        .map((a: any) => ({ id: a.id, nome: a.name }));

      setDbProducts([...activeAdditions, ...defaultsIncluded]);
    } catch (err) {
      handleError(err, { domain: 'producao', operation: 'buildAiProductList', showToast: false });
      const constantProducts = DAILY_PRODUCTION_PRODUCTS.map((product, index) => ({ id: -(index + 1), nome: product }));
      setDbProducts(constantProducts);
    }
  };

  // Estado para texto intermediário (enquanto fala)
  const [interimText, setInterimText] = useState("");
  const [voiceStatus, setVoiceStatus] = useState<string>("");

  const toggleVoiceInput = () => {
    if (isListening) {
      if (recognitionRef.current) {
        recognitionRef.current.manualStop = true;
        try { recognitionRef.current.stop(); } catch (e) { }
      }
      setIsListening(false);
      setInterimText("");
      setVoiceStatus("");
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setVoiceStatus("❌ Navegador não suporta. Use Chrome ou Edge.");
      return;
    }

    let retryCount = 0;
    const maxRetries = 3;

    const startRecognition = () => {
      setVoiceStatus("🔄 Conectando ao microfone...");

      const recognition = new SpeechRecognition();
      recognitionRef.current = recognition;
      recognition.lang = 'pt-BR';
      recognition.continuous = false;
      recognition.interimResults = true;

      recognition.onstart = () => {
        setIsListening(true);
        setVoiceStatus("🎤 Escutando... Fale agora!");
        retryCount = 0;
      };

      recognition.onaudiostart = () => {
        setVoiceStatus("🎤 Microfone ativo - Fale agora!");
      };

      recognition.onspeechstart = () => {
        setVoiceStatus("👂 Detectando sua voz...");
      };

      recognition.onresult = (event: any) => {
        let finalText = '';
        let interim = '';
        for (let i = 0; i < event.results.length; i++) {
          const t = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalText += t;
          } else {
            interim += t;
          }
        }

        if (interim) {
          setInterimText(interim);
          setVoiceStatus("✍️ Transcrevendo: " + interim.substring(0, 30) + "...");
        }

        if (finalText) {
          setWhatsappMessage(prev => prev + (prev ? '\n' : '') + finalText);
          setInterimText("");
          setVoiceStatus("✅ Texto adicionado! Continue falando...");
        }
      };

      recognition.onspeechend = () => {
        setVoiceStatus("⏸️ Pausa detectada, aguardando mais fala...");
      };

      recognition.onerror = (event: any) => {
        wideWarn('producao.voice_error', `Erro de reconhecimento de voz: ${event.error}`, { domain: 'producao', attributes: { error: event.error } });

        if (event.error === 'network') {
          // Detectar Brave Browser
          const isBrave = (navigator as any).brave !== undefined;

          if (retryCount < maxRetries) {
            retryCount++;
            setVoiceStatus(`⚠️ Erro de conexão. Tentativa ${retryCount}/${maxRetries}...`);
            setTimeout(() => {
              if (recognitionRef.current && !recognitionRef.current.manualStop) {
                startRecognition();
              }
            }, 1000);
            return;
          } else {
            if (isBrave) {
              setVoiceStatus("❌ BRAVE BROWSER: Clique no leão 🦁 na barra de endereço → Desative 'Shields' → Recarregue a página");
            } else {
              setVoiceStatus("❌ Serviço de voz do Google indisponível. Tente Chrome ou Edge.");
            }
            setIsListening(false);
            if (recognitionRef.current) recognitionRef.current.manualStop = true;
            return;
          }
        }

        if (event.error === 'not-allowed') {
          setVoiceStatus("❌ Microfone bloqueado! Clique no 🔒 na barra de endereço e permita.");
          setIsListening(false);
          if (recognitionRef.current) recognitionRef.current.manualStop = true;
          return;
        }

        if (event.error === 'audio-capture') {
          setVoiceStatus("❌ Microfone não encontrado. Conecte um microfone.");
          setIsListening(false);
          if (recognitionRef.current) recognitionRef.current.manualStop = true;
          return;
        }

        if (event.error === 'no-speech') {
          setVoiceStatus("🔇 Nenhum som detectado. Fale mais alto ou aproxime-se do microfone.");
        }
      };

      recognition.onend = () => {
        if (recognitionRef.current && !recognitionRef.current.manualStop) {
          setVoiceStatus("🔄 Reiniciando escuta...");
          setTimeout(() => {
            if (recognitionRef.current && !recognitionRef.current.manualStop) {
              startRecognition();
            }
          }, 100);
        } else {
          setIsListening(false);
          setInterimText("");
          setVoiceStatus("");
        }
      };

      try {
        recognition.start();
      } catch (e: any) {
        setVoiceStatus("❌ Erro ao iniciar: " + e.message);
        setIsListening(false);
      }
    };

    startRecognition();
  };

  const closeImportModal = () => {
    setIsImportModalOpen(false);
  };

  // Importações de utils (assumindo que foram importadas no topo do arquivo, mas como replace_file_content edita blocos, vou remover as definições locais)

  // ESTAS FUNÇÕES AGORA VÊM DE @/lib/stringUtils
  // normalizeName, levenshtein, similarity foram movidas.


  const matchAiItemsToDb = (items: Array<{ name: string; quantity: number }>) => {
    const suggestionsFor = (name: string) => {
      const scored = dbProducts.map(p => ({
        id: p.id,
        nome: p.nome,
        score: similarity(name, p.nome)
      })).sort((a, b) => b.score - a.score).slice(0, 5);
      return scored;
    };

    const mapped = items.map(item => {
      const sugg = suggestionsFor(item.name);
      const best = sugg[0];
      const threshold = 0.72;
      const isGood = best && best.score >= threshold;
      return {
        originalName: item.name,
        quantity: item.quantity,
        matchedName: isGood ? best.nome : undefined,
        matchedId: isGood ? best.id : undefined,
        confidence: best ? best.score : 0,
        suggestions: sugg,
        selected: isGood
      };
    });

    setMatchedItems(mapped);
  };

  const processWhatsappWithAI = async () => {
    if (!whatsappMessage.trim()) {
      toast({ title: 'Cole a mensagem do WhatsApp', variant: 'destructive' });
      return;
    }
    setIsProcessingAI(true);
    try {
      const SUPABASE_URL = (import.meta as any).env?.VITE_SUPABASE_URL || supabase.supabaseUrl;
      const SUPABASE_ANON_KEY = (import.meta as any).env?.VITE_SUPABASE_PUBLISHABLE_KEY || (supabase as any).supabaseKey;
      const resp = await fetch(`${SUPABASE_URL}/functions/v1/process-daily-production-ai`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
        },
        body: JSON.stringify({ dailyMessage: whatsappMessage })
      });
      if (!resp.ok) {
        const txt = await resp.text();
        throw new Error(`Erro IA: ${resp.status} ${resp.statusText} - ${txt}`);
      }
      const data = await resp.json();
      const items = Array.isArray(data.items) ? data.items.map((it: any) => ({ name: it.name, quantity: it.quantity })) : [];
      setAiItems(items);
      matchAiItemsToDb(items);
      toast({ title: 'Mensagem processada com IA', description: `${items.length} itens identificados` });
    } catch (e: any) {
      handleError(e, { domain: 'producao', operation: 'processAiMessage', showToast: false });
      toast({ title: 'Erro ao processar com IA', description: e?.message || 'Falha desconhecida', variant: 'destructive' });
    } finally {
      setIsProcessingAI(false);
    }
  };

  const addSelectedAiItemsToEntries = () => {
    // Permitir lançar todos os itens selecionados, mesmo sem correspondência automática
    const toAdd = matchedItems.filter(mi => mi.selected && mi.quantity > 0);
    if (toAdd.length === 0) {
      toast({ title: 'Selecione itens para lançar', variant: 'destructive' });
      return;
    }
    const newEntries: ProductionEntry[] = toAdd.map(mi => ({
      id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      product_name: mi.matchedName || mi.originalName,
      quantity: mi.quantity
    }));
    setProductionEntries(prev => [...prev, ...newEntries]);
    toast({ title: 'Itens lançados', description: `${toAdd.length} itens reconhecidos lançados` });
    closeImportModal();
  };

  const addProductEntry = () => {
    if (!selectedProduct || !newQuantity || parseFloat(newQuantity) <= 0) {
      toast({
        title: "Dados incompletos",
        description: "Selecione um produto e informe uma quantidade válida",
        variant: "destructive"
      });
      return;
    }

    const newEntry: ProductionEntry = {
      id: Date.now().toString(),
      product_name: selectedProduct,
      quantity: parseFloat(newQuantity)
    };

    setProductionEntries(prev => [...prev, newEntry]);

    toast({
      title: "Produto lançado",
      description: `${selectedProduct} - ${newQuantity} unidades`,
      duration: 2000
    });

    closeAddModal();
  };

  const updateEntry = (id: string, field: keyof ProductionEntry, value: any) => {
    setProductionEntries(prev =>
      prev.map(entry =>
        entry.id === id ? { ...entry, [field]: value } : entry
      )
    );
  };

  const removeEntry = (id: string) => {
    setProductionEntries(prev => prev.filter(entry => entry.id !== id));
    toast({
      title: "Produto removido",
      description: "Item removido da lista de produção",
      duration: 2000
    });
  };

  const handleSubmit = async () => {
    if (productionEntries.length === 0) {
      toast({ title: "Adicione pelo menos um produto", variant: "destructive" });
      return;
    }
    setSelectedDate(date);
    setIsDateModalOpen(true);
  };

  const confirmAndSubmit = async () => {
    if (!user) {
      toast({ title: "Usuário não autenticado", variant: "destructive" });
      return;
    }

    setIsLoading(true);
    const startTime = performance.now();

    try {
      await withTrace('producao.diaria.registrar', async () => {
        // Find distinct product names
        const uniqueProductNames = Array.from(new Set(productionEntries.map(e => e.product_name.trim().toLowerCase())));

        // Fetch matching master products
        const masterMap: Record<string, number> = {};
        if (uniqueProductNames.length > 0) {
          const { data: masters, error: mError } = await supabase
            .from('produtos_master')
            .select('id, nome')
            .filter('ativo', 'eq', true); // or just get everything since it is an exact match lookup

          if (!mError && masters) {
            // Fallback similarity matching
            masters.forEach(m => {
              if (m.nome) {
                const cleanMasterName = m.nome.trim().toLowerCase();
                masterMap[cleanMasterName] = m.id;
              }
            });
          }
        }

        const payload = productionEntries.map(entry => {
          const cleanEntryName = entry.product_name.trim().toLowerCase();

          // Exact match
          let matchedId = masterMap[cleanEntryName] || null;

          // Very basic fuzzy fallback just in case
          if (!matchedId) {
            const possibleKeys = Object.keys(masterMap);
            for (const k of possibleKeys) {
              if (k.includes(cleanEntryName) || cleanEntryName.includes(k)) {
                matchedId = masterMap[k];
                break;
              }
            }
          }

          return {
            date: selectedDate,
            product_name: entry.product_name,
            quantity: entry.quantity,
            produto_master_id: matchedId,
            created_by: user.id,
          };
        });

        const { error } = await supabase
          .from('daily_production')
          .insert(payload);

        if (error) throw error;
      }, telemetryAttrs);

      const durationMs = Math.round(performance.now() - startTime);
      const totalQuantity = productionEntries.reduce((sum, e) => sum + e.quantity, 0);

      wideInfo('producao.diaria.registrada', 'Produção diária registrada com sucesso', {
        attributes: {
          'producao.quantidade_produtos': productionEntries.length,
          'producao.quantidade_total': totalQuantity,
          'producao.data': selectedDate,
          'duration_ms': durationMs,
        },
      });
      recordProductionRecord({ 'producao.data': selectedDate });
      recordOperationDuration('producao.diaria', durationMs);

      toast({
        title: "Produção registrada com sucesso!",
        description: `${productionEntries.length} produtos salvos para ${formatDateBR(selectedDate)}`,
        duration: 3000
      });

      // Limpar formulário
      setProductionEntries([]);
      setSearchTerm("");
      setIsDateModalOpen(false);

    } catch (error) {
      const durationMs = Math.round(performance.now() - startTime);
      wideError('producao.diaria.erro', 'Falha ao registrar produção diária', {
        attributes: {
          'error.message': error instanceof Error ? error.message : String(error),
          'duration_ms': durationMs,
        },
      });
      recordError('producao_diaria', 'registrar');
      handleError(error, { domain: 'producao', operation: 'registerProduction', showToast: false });
      toast({ title: 'Erro ao registrar produção', variant: 'destructive' });
    } finally {
      setIsLoading(false);
    }
  };

  // MIA action hook — wired after handleSubmit is defined
  useMiaProducaoDiariaActions({
    setActiveTab,
    setDate,
    setSearchTerm,
    setIsAddModalOpen,
    setIsImportModalOpen,
    handleSubmit,
    setHistoryFilter,
    setAnalyticsPreset: applyAnalyticsPreset,
    setAnalyticsViewMode,
    setIsManageModalOpen,
    productionEntries,
  });

  // Função para registrar novo produto no banco
  const registerNewProduct = async () => {
    if (!newProductName.trim()) {
      toast({ title: "Nome do produto é obrigatório", variant: "destructive" });
      return;
    }

    // Registro global de produto (sem loja)

    setIsCreatingProduct(true);

    try {
      const productData = {
        loja_id: null,
        name: newProductName.trim(),
        active: true,
        created_by: user?.id || null,
      };

      const { error } = await supabase
        .from('daily_production_products')
        .insert(productData);

      if (error) throw error;

      toast({
        title: "Produto registrado com sucesso!",
        description: `${newProductName} foi adicionado à lista de produtos`,
        duration: 3000
      });

      // Limpar modal
      setNewProductName("");
      setIsNewProductModalOpen(false);

      // Recarregar lista de produtos (padrões + adicionados − excluídos)
      try {
        const { data: additionsData } = await supabase
          .from('daily_production_products')
          .select('id, name, active');

        const { data: exclusionsData } = await supabase
          .from('daily_production_exclusions')
          .select('name');

        const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
        const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
        const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
        const finalList = Array.from(new Set([...activeAdditions, ...defaultsIncluded]));
        setAllProducts(finalList);

        if (isImportModalOpen) {
          const activeAdditionsForIA = (additionsData || []).filter((a: any) => a.active).map((a: any) => ({ id: a.id, nome: a.name }));
          const defaultsIncludedForIA = defaultsIncluded.map((product, index) => ({ id: -(index + 1), nome: product }));
          setDbProducts([...activeAdditionsForIA, ...defaultsIncludedForIA]);
        }
      } catch (err) {
        handleError(err, { domain: 'producao', operation: 'reloadProductionListAfterRegister', showToast: false });
      }

    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'registerProduct', showToast: false });
      const message = (error?.message || '').toLowerCase();
      if (error?.code === '23505' || message.includes('duplicate') || message.includes('unique')) {
        toast({
          title: 'Produto já existe',
          description: 'Já há um produto com este nome nesta loja.',
          variant: 'destructive'
        });
      } else {
        toast({
          title: 'Erro ao registrar produto',
          description: error?.message || 'Tente novamente mais tarde.',
          variant: 'destructive'
        });
      }
    } finally {
      setIsCreatingProduct(false);
    }
  };

  // Remover produto adicionado (custom) da lista de produção
  const removeDailyAddition = async (id: number) => {
    try {
      const { error } = await supabase
        .from('daily_production_products')
        .delete()
        .eq('id', id);
      if (error) throw error;

      toast({ title: 'Produto removido da lista de produção' });

      const { data: additionsData } = await supabase
        .from('daily_production_products')
        .select('id, name, active');
      setDailyAdditions(additionsData || []);
      const { data: exclusionsData } = await supabase
        .from('daily_production_exclusions')
        .select('name');
      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
      const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
      setAllProducts(Array.from(new Set([...activeAdditions, ...defaultsIncluded])));
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'removeDailyProduct', showToast: false });
      toast({ title: 'Erro ao remover produto', variant: 'destructive' });
    }
  };

  // Incluir/ocultar produto padrão na lista de produção
  const setDefaultProductIncluded = async (name: string, included: boolean) => {
    try {
      if (included) {
        const { error } = await supabase
          .from('daily_production_exclusions')
          .delete()
          .eq('name', name);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('daily_production_exclusions')
          .insert({ loja_id: null, name, created_by: user?.id || null });
        if (error) throw error;
      }
      const { data: exclusionsData } = await supabase
        .from('daily_production_exclusions')
        .select('name');
      setDailyExclusions((exclusionsData || []).map((e: any) => e.name));
      const { data: additionsData } = await supabase
        .from('daily_production_products')
        .select('id, name, active');
      setDailyAdditions(additionsData || []);

      const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
      const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
      const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
      setAllProducts(Array.from(new Set([...activeAdditions, ...defaultsIncluded])));
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'updateDefaultProductExclusion', showToast: false });
      toast({ title: 'Erro ao atualizar lista', variant: 'destructive' });
    }
  };

  const toggleSelectForDeletion = (name: string) => {
    setSelectedForDeletion(prev => prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name]);
  };

  const deleteSelectedProducts = async () => {
    if (selectedForDeletion.length === 0) return;
    setIsDeletingProducts(true);
    try {
      const additionsIndex = new Map(
        dailyAdditions.filter(a => a.active).map(a => [a.name, a.id])
      );

      const ops = selectedForDeletion.map(name => {
        const id = additionsIndex.get(name);
        return id ? removeDailyAddition(id) : setDefaultProductIncluded(name, false);
      });

      await Promise.all(ops);

      setSelectedForDeletion([]);
      setIsDeleteMode(false);
      toast({ title: 'Itens removidos da lista', description: `${ops.length} removidos` });
    } catch (e) {
      handleError(e, { domain: 'producao', operation: 'deleteSelectedProducts', showToast: false });
      toast({ title: 'Erro ao remover itens', variant: 'destructive' });
    } finally {
      setIsDeletingProducts(false);
    }
  };

  // Funções para histórico
  const loadHistory = async () => {
    try {
      const { data, error } = await supabase
        .from('daily_production')
        .select('*')
        .gte('date', dateRange.start)
        .lte('date', dateRange.end)
        .order('date', { ascending: false });

      if (error) throw error;
      setHistory(data || []);
    } catch (error) {
      handleError(error, { domain: 'producao', operation: 'loadHistory', showToast: false });
    }
  };

  const deleteHistoryEntry = async (id: string) => {
    try {
      const confirmed = window.confirm('Tem certeza que deseja deletar este lançamento de produção?');
      if (!confirmed) return;
      const { error } = await supabase
        .from('daily_production')
        .delete()
        .eq('id', id);
      if (error) throw error;
      toast({ title: 'Produção deletada', description: 'O lançamento foi removido com sucesso.' });
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'deleteHistoryEntry', showToast: false });
      const msg = (error?.message || '').toLowerCase();
      if (msg.includes('permission') || msg.includes('rls')) {
        toast({ title: 'Sem permissão para deletar', description: 'Apenas quem lançou pode deletar este registro.', variant: 'destructive' });
      } else {
        toast({ title: 'Erro ao deletar', description: error?.message || 'Tente novamente mais tarde.', variant: 'destructive' });
      }
    }
  };

  const openEditModal = (entry: HistoryEntry) => {
    setEditingEntry(entry);
    setEditProduct(entry.product_name);
    setEditQuantity(entry.quantity.toString());
    setEditDate(entry.date);
    setIsEditMode(true);
  };

  const closeEditModal = () => {
    setIsEditMode(false);
    setEditingEntry(null);
    setEditProduct("");
    setEditQuantity("");
    setEditDate("");
  };

  const editHistoryEntry = async () => {
    if (!editingEntry || !editProduct || !editQuantity || !editDate) {
      toast({
        title: "Dados incompletos",
        description: "Preencha todos os campos",
        variant: "destructive"
      });
      return;
    }

    try {
      const { error } = await supabase
        .from('daily_production')
        .update({
          product_name: editProduct,
          quantity: parseFloat(editQuantity),
          date: editDate
        })
        .eq('id', editingEntry.id);

      if (error) throw error;

      toast({
        title: 'Produção atualizada',
        description: 'A produção foi editada com sucesso.'
      });

      closeEditModal();
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'editProduction', showToast: false });
      const msg = (error?.message || '').toLowerCase();
      if (msg.includes('permission') || msg.includes('rls')) {
        toast({
          title: 'Sem permissão para editar',
          description: 'Apenas quem lançou pode editar este registro.',
          variant: 'destructive'
        });
      } else {
        toast({
          title: 'Erro ao editar',
          description: error?.message || 'Tente novamente mais tarde.',
          variant: 'destructive'
        });
      }
    }
  };

  // Estados para edição de DATA em lote
  const [isEditDateBatchModalOpen, setIsEditDateBatchModalOpen] = useState(false);
  const [batchOldDate, setBatchOldDate] = useState("");
  const [batchNewDate, setBatchNewDate] = useState("");

  const openBatchDateEdit = (date: string) => {
    setBatchOldDate(date);
    setBatchNewDate(date);
    setIsEditDateBatchModalOpen(true);
  };

  const updateProductionDate = async () => {
    if (!batchNewDate) {
      toast({ title: "Selecione uma nova data", variant: "destructive" });
      return;
    }

    try {
      // Atualiza todas as entradas daquele dia para a nova data
      const { error } = await supabase
        .from('daily_production')
        .update({ date: batchNewDate })
        .eq('date', batchOldDate);

      if (error) throw error;

      toast({
        title: "Data de produção atualizada",
        description: `Produção movida de ${formatDateBR(batchOldDate)} para ${formatDateBR(batchNewDate)}`
      });

      setIsEditDateBatchModalOpen(false);
      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'updateProductionDate', showToast: false });
      toast({
        title: 'Erro ao mover produção',
        description: error?.message || 'Verifique suas permissões.',
        variant: 'destructive'
      });
    }
  };

  const deleteProductionBatch = async (date: string) => {
    const confirmed = window.confirm(`ATENÇÃO: Isso apagará TODOS os itens lançados no dia ${formatDateBR(date)}. Tem certeza?`);
    if (!confirmed) return;

    try {
      const { error } = await supabase
        .from('daily_production')
        .delete()
        .eq('date', date);

      if (error) throw error;

      toast({
        title: "Produção do dia removida",
        description: `Todos os registros de ${formatDateBR(date)} foram apagados.`
      });

      await loadHistory();
    } catch (error: any) {
      handleError(error, { domain: 'producao', operation: 'deleteDayProduction', showToast: false });
      toast({
        title: 'Erro ao apagar produção',
        description: error?.message || 'Verifique suas permissões.',
        variant: 'destructive'
      });
    }
  };

  // Funções para analytics
  const loadAnalytics = async () => {
    try {
      // 1. Definir períodos
      const currentStart = parseISO(analyticsDateRange.start);
      const currentEnd = parseISO(analyticsDateRange.end);
      const daysDiff = differenceInDays(currentEnd, currentStart) + 1;

      const previousStart = subDays(currentStart, daysDiff);
      const previousEnd = subDays(currentEnd, daysDiff);

      // 2. Buscar dados (Periodo Atual + Anterior)
      const { data, error } = await supabase
        .from('daily_production')
        .select('*')
        .gte('date', formatDateISO(previousStart))
        .lte('date', formatDateISO(currentEnd));

      if (error) throw error;

      const allEntries = data || [];

      // 3. Separar dados
      const currentEntries = allEntries.filter(e => e.date >= analyticsDateRange.start && e.date <= analyticsDateRange.end);
      const previousEntries = allEntries.filter(e => e.date >= formatDateISO(previousStart) && e.date <= formatDateISO(previousEnd));

      // 4. Calcular KPIs Gerais
      const totalProduction = currentEntries.reduce((sum, e) => sum + e.quantity, 0);
      const previousTotal = previousEntries.reduce((sum, e) => sum + e.quantity, 0);

      const momGrowth = previousTotal === 0 ? 100 : ((totalProduction - previousTotal) / previousTotal) * 100;

