import { useMemo } from 'react';
import { useMiaActions } from '@/hooks/useMiaActions';
import type { MiaActionHandler } from '@/types/mia';

export interface ProducaoDiariaMiaInterface {
  setActiveTab: (v: string) => void;
  setDate: (v: string) => void;
  setSearchTerm: (v: string) => void;
  setIsAddModalOpen: (v: boolean) => void;
  setIsImportModalOpen: (v: boolean) => void;
  handleSubmit: () => void;
  setHistoryFilter: (v: string) => void;
  setAnalyticsPreset: (v: string) => void;
  setAnalyticsViewMode: (v: string) => void;
  setIsManageModalOpen: (v: boolean) => void;
  productionEntries: any[];
}

export function useMiaProducaoDiariaActions(iface: ProducaoDiariaMiaInterface): void {
  const {
    setActiveTab,
    setDate,
    setSearchTerm,
    setIsAddModalOpen,
    setIsImportModalOpen,
    handleSubmit,
    setHistoryFilter,
    setAnalyticsPreset,
    setAnalyticsViewMode,
    setIsManageModalOpen,
    productionEntries,
  } = iface;

  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
    // ── Select tab ──
    prod_diaria_select_tab: {
      id: 'prod_diaria_select_tab',
      description: 'Selecionar aba da producao diaria (entry/history/analytics/pedido)',
      execute: (data) => {
        if (data?.tab) setActiveTab(data.tab);
      },
    },

    // ── Set production date ──
    prod_diaria_set_date: {
      id: 'prod_diaria_set_date',
      description: 'Definir data da producao diaria',
      execute: (data) => {
        if (data?.date) setDate(data.date);
      },
    },

    // ── Search products ──
    prod_diaria_search: {
      id: 'prod_diaria_search',
      description: 'Buscar produto na lista de producao',
      execute: (data) => {
        if (data?.search !== undefined) setSearchTerm(data.search);
      },
    },

    // ── Open add product modal ──
    prod_diaria_add_product: {
      id: 'prod_diaria_add_product',
      description: 'Abrir modal para adicionar produto na producao',
      execute: () => {
        setIsAddModalOpen(true);
      },
    },

    // ── Open WhatsApp import modal ──
    prod_diaria_import_whatsapp: {
      id: 'prod_diaria_import_whatsapp',
      description: 'Abrir modal de importacao via WhatsApp/IA',
      execute: () => {
        setIsImportModalOpen(true);
      },
    },

    // ── Submit production ──
    prod_diaria_submit: {
      id: 'prod_diaria_submit',
      description: 'Salvar registro de producao diaria',
      execute: () => {
        handleSubmit();
      },
    },

    // ── History filter ──
    prod_diaria_history_filter: {
      id: 'prod_diaria_history_filter',
      description: 'Filtrar historico de producao por busca',
      execute: (data) => {
        if (data?.filter !== undefined) setHistoryFilter(data.filter);
      },
    },

    // ── Analytics preset ──
    prod_diaria_analytics_preset: {
      id: 'prod_diaria_analytics_preset',
      description: 'Definir periodo do analytics de producao (7d/30d/90d)',
      execute: (data) => {
        if (data?.preset) setAnalyticsPreset(data.preset);
      },
    },

    // ── Analytics view mode ──
    prod_diaria_analytics_view: {
      id: 'prod_diaria_analytics_view',
      description: 'Definir modo de visualizacao do analytics (daily/monthly)',
      execute: (data) => {
        if (data?.view) setAnalyticsViewMode(data.view);
      },
    },

    // ── Open manage products modal ──
    prod_diaria_manage_products: {
      id: 'prod_diaria_manage_products',
      description: 'Abrir modal de gerenciamento de produtos da lista diaria',
      execute: () => {
        setIsManageModalOpen(true);
      },
    },

    // ── Clear filters ──
    clear_filters: {
      id: 'clear_filters',
      description: 'Limpar filtros da producao diaria',
      execute: () => {
        setSearchTerm('');
        setHistoryFilter('');
      },
    },
  }), [
    setActiveTab,
    setDate,
    setSearchTerm,
    setIsAddModalOpen,
    setIsImportModalOpen,
    handleSubmit,
    setHistoryFilter,
    setAnalyticsPreset,
    setAnalyticsViewMode,
    setIsManageModalOpen,
    productionEntries,
  ]);

  useMiaActions('/producao-diaria', handlers);
}

