import jsPDF, { GState } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

/**
 * Gerador de Relatório PDF de Produção Diária.
 *
 * Relatório de alto nível: totais por produto, consolidado de TODAS as lojas.
 * Segue o padrão visual world-class do Cofre/DRE: border Momma green dupla,
 * logo header, watermark central, header/footer por página com paginação,
 * resumo executivo e tabela analítica paginada.
 *
 * O helper `aggregateProducao` é PURO (sem jsPDF) e testável isoladamente.
 */

// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────

export interface ProducaoEntry {
  date: string;
  product_name: string;
  quantity: number;
}

export interface ProducaoAggregate {
  totalQuantity: number;
  /** Nº de produtos distintos (por nome). */
  distinctProducts: number;
  /** Nº de datas distintas com produção. */
  activeDays: number;
  /** totalQuantity / activeDays (0 se activeDays = 0). */
  avgPerDay: number;
  /** Ordenado por quantity desc, depois nome asc. */
  byProduct: Array<{ product_name: string; quantity: number }>;
}

export interface GenerateProducaoDiariaPdfParams {
  entries: ProducaoEntry[];
  dateStart: string; // yyyy-MM-dd
  dateEnd: string; // yyyy-MM-dd
}

// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────

/**
 * Agrega lançamentos de produção em totais de alto nível.
 *
 * - Produtos com mesmo nome têm suas quantidades somadas.
 * - Dias são contados por datas distintas (mesma data conta 1).
 * - Lista vazia retorna tudo zerado e arrays vazios.
 */
export function aggregateProducao(entries: ProducaoEntry[]): ProducaoAggregate {
  const productTotals = new Map<string, number>();
  const distinctDates = new Set<string>();
  let totalQuantity = 0;

  for (const entry of entries) {
    const quantity = Number(entry.quantity) || 0;
    totalQuantity += quantity;

    const productKey = entry.product_name;
    productTotals.set(productKey, (productTotals.get(productKey) ?? 0) + quantity);

    if (entry.date) {
      distinctDates.add(entry.date);
    }
  }

  const activeDays = distinctDates.size;

  const byProduct = Array.from(productTotals.entries())
    .map(([product_name, quantity]) => ({ product_name, quantity }))
    .sort((a, b) => {
      if (b.quantity !== a.quantity) return b.quantity - a.quantity;
      return a.product_name.localeCompare(b.product_name, 'pt-BR');
    });

  return {
    totalQuantity,
    distinctProducts: productTotals.size,
    activeDays,
    avgPerDay: activeDays === 0 ? 0 : totalQuantity / activeDays,
    byProduct,
  };
}

// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
// Replicados (não importados de outra feature) para respeitar boundaries FSD.

const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];

/**
 * Quantidades podem ser fracionárias (ex.: 0.5). Mostra até 2 casas decimais,
 * suprimindo zeros à direita (inteiros ficam sem casas).
 */
const numberFmt = (v: number): string =>
  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });

const avgFmt = (v: number): string =>
  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

const loadImage = (url: string): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
    img.src = url;
  });

// ───────────────────────── GERADOR DE PDF ─────────────────────────

export async function generateProducaoDiariaPdf(
  params: GenerateProducaoDiariaPdfParams,
): Promise<void> {
  const { entries, dateStart, dateEnd } = params;
  const agg = aggregateProducao(entries);

  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(
    () => null,
  );
  const watermarkLogo = await loadImage(
    '/logo sistema/android-chrome-512x512.png',
  ).catch(() => null);

  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  const periodoLabel = `${format(
    new Date(dateStart + 'T12:00:00'),
    'dd/MM/yyyy',
    { locale: ptBR },
  )} a ${format(new Date(dateEnd + 'T12:00:00'), 'dd/MM/yyyy', { locale: ptBR })}`;

  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
  const drawPageExtras = (hookData: { pageNumber?: number }) => {
    const currentPage = hookData.pageNumber || 1;

    // Bordas premium (dupla linha)
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
    doc.setLineWidth(0.2);
    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');

    // Logo cabeçalho — preserva aspect ratio
    if (logoHeader) {
      const ratio = logoHeader.height / logoHeader.width;
      let expectedWidth = 45;
      let expectedHeight = expectedWidth * ratio;
      if (expectedHeight > 18) {
        expectedHeight = 18;
        expectedWidth = expectedHeight / ratio;
      }
      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
    }

    // Título e subtítulo (alinhados à direita)
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.setFontSize(16);
    doc.text('RELATÓRIO DE PRODUÇÃO DIÁRIA', pageWidth - 15, 20, { align: 'right' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...MOMMA_GREEN);
    doc.text('TOTAIS POR PRODUTO — CONSOLIDADO', pageWidth - 15, 25, {
      align: 'right',
    });

    doc.setTextColor(...MOMMA_GREEN_SOFT);
    doc.setFontSize(8);
    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
    doc.text('Unidade: Todas as lojas', pageWidth - 15, 35, { align: 'right' });

    // Linha separadora abaixo do header
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.line(15, 43, pageWidth - 15, 43);

    // Footer com paginação
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...MOMMA_GREEN);
    const totalPages = doc.getNumberOfPages();
    doc.text(
      `Relatório de Produção Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
      pageWidth / 2,
      pageHeight - 12,
      { align: 'center' },
    );

    // Watermark sutil ao centro
    if (watermarkLogo) {
      try {
        doc.setGState(new GState({ opacity: 0.08 }));
        const wSize = 200;
        doc.addImage(
          watermarkLogo,
          'PNG',
          (pageWidth - wSize) / 2,
          (pageHeight - wSize) / 2,
          wSize,
          wSize,
        );
        doc.setGState(new GState({ opacity: 1.0 }));
      } catch {
        /* fallback silencioso */
      }
    }
  };

  // Página 1: header desenhado manualmente (resumo é desenhado fora do autoTable)
  drawPageExtras({ pageNumber: 1 });

  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
  let cursorY = 52;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('RESUMO EXECUTIVO DO PERÍODO', 15, cursorY);
  cursorY += 5;

  const boxX = 15;
  const boxW = pageWidth - 30;
  const boxH = 22;

  doc.setFillColor(248, 250, 248);
  doc.setDrawColor(...MOMMA_GREEN);
  doc.setLineWidth(0.4);
  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');

  const colW = boxW / 4;
  const drawMetric = (
    label: string,
    value: string,
    colIndex: number,
    valueFontSize: number,
  ) => {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(valueFontSize);
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.text(value, boxX + colW * colIndex + 4, cursorY + 14);
  };

  drawMetric('TOTAL PRODUZIDO', numberFmt(agg.totalQuantity), 0, 13);
  drawMetric('PRODUTOS DISTINTOS', numberFmt(agg.distinctProducts), 1, 13);
  drawMetric('DIAS COM PRODUÇÃO', numberFmt(agg.activeDays), 2, 13);
  drawMetric('MÉDIA / DIA', avgFmt(agg.avgPerDay), 3, 13);

  cursorY += boxH + 8;

  // ───────────────────────── TABELA: PRODUÇÃO POR PRODUTO ─────────────────────────
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('PRODUÇÃO POR PRODUTO', 15, cursorY);
  cursorY += 3;

  const productBody = agg.byProduct.map((p) => [p.product_name, numberFmt(p.quantity)]);
  productBody.push(['TOTAL GERAL', numberFmt(agg.totalQuantity)]);

  autoTable(doc, {
    startY: cursorY,
    head: [['Produto', 'Quantidade']],
    body: productBody,
    theme: 'plain',
    styles: {
      fontSize: 8,
      font: 'helvetica',
      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
      textColor: [60, 60, 60],
      lineColor: [230, 230, 230],
      lineWidth: { bottom: 0.1 },
    },
    headStyles: {
      fillColor: MOMMA_GREEN,
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 8.5,
      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
      lineWidth: 0,
    },
    alternateRowStyles: { fillColor: [248, 250, 248] },
    columnStyles: {
      0: { cellWidth: 'auto' },
      1: { cellWidth: 35, halign: 'right', fontStyle: 'bold' },
    },
    didParseCell: (data) => {
      // Última linha = Total Geral em destaque
      if (data.section === 'body' && data.row.index === productBody.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [236, 242, 237];
        data.cell.styles.textColor = MOMMA_GREEN_DARK;
      }
    },
    didDrawPage: (hk) => {
      if (hk.pageNumber > 1) {
        drawPageExtras(hk);
      }
    },
    margin: { top: 50, left: 15, right: 15, bottom: 20 },
  });

  // ───────────────────────── PERSISTÊNCIA ─────────────────────────
  doc.save(`producao-diaria_${dateStart}_a_${dateEnd}.pdf`);
}

