// MIA Code-Native (Onda 2) — Skill: Lançar Produção Diária.
//
// Pegadinhas Momma documentadas em memória:
//  - Doces saudáveis com validade 3-5d (shelf-life curto)
//  - Produção SEMPRE associada à loja selecionada (StoreSelector)
//  - Fechamento gera daily_production_products
//
// DOM disponível (DailyProductionForm.tsx):
//  - data-mia-action="abrir-modal-adicionar" (abre dialog)
//  - data-mia-modal="modal-adicionar"
//  - data-mia-filter="produto" (select com lista)
//  - data-mia-field="produto" (input manual, novo produto)
//  - data-mia-field="quantidade"
//  - data-mia-action="adicionar-produto" (lançar entry)
//  - data-mia-action="cancelar-modal-adicionar"
//  - data-mia-field="buscar-produto" (search na lista existente)

import { z } from 'https://esm.sh/zod@3.23.8'
import type { SkillModule, SkillAmbiguity, SkillBuildContext } from './_types.ts'
import type { GlassBoxStep } from '../glass-box-agent-loop.ts'

const ProdutoSchema = z.object({
    nome: z.string().min(1),
    quantidade: z.number().positive(),
})

const Input = z.object({
    loja_nome: z.string().optional()
        .describe('Nome da loja (ex: "Fábrica", "Asa Norte"). Default: storeName atual.'),
    produtos: z.array(ProdutoSchema).min(1)
        .describe('Lista de produtos lançados com nome + quantidade. Mínimo 1.'),
})

export type LancarProducaoDiariaInput = z.infer<typeof Input>

function detectAmbiguities(_rawIntent: string, _parsed: LancarProducaoDiariaInput): SkillAmbiguity[] {
    return []
}

function build(entities: LancarProducaoDiariaInput, ctx: SkillBuildContext): GlassBoxStep[] {
    const steps: GlassBoxStep[] = []

    // STATE-DIFF: troca loja só se diferente
    if (entities.loja_nome && ctx.storeName !== entities.loja_nome) {
        steps.push({
            op: 'switch_store',
            store: entities.loja_nome,
            label: `Trocar loja para ${entities.loja_nome}`,
            expects: { store_changes_to: entities.loja_nome },
        })
        steps.push({ op: 'pause', ms: 400, label: 'Aguardar contexto da loja' })
    }

    // STATE-DIFF: navega só se necessário
    if (ctx.route !== '/producao-diaria' && !ctx.route?.startsWith('/producao-diaria/')) {
        steps.push({
            op: 'navigate',
            route: '/producao-diaria',
            label: 'Ir para Produção Diária',
            expects: { route_changes_to: '/producao-diaria' },
        })
        steps.push({ op: 'pause', ms: 800, label: 'Aguardar Page Model' })
    }

    // Para cada produto: abrir modal → preencher → lançar → próximo
    // (modal fecha automaticamente após adicionar-produto)
    for (let i = 0; i < entities.produtos.length; i++) {
        const produto = entities.produtos[i]
        const modalAlreadyOpen = i === 0 && ctx.openModals.includes('modal-adicionar')
        if (!modalAlreadyOpen) {
            steps.push({
                op: 'wait',
                action: 'abrir-modal-adicionar',
                timeoutMs: 2000,
                label: 'Aguardar botão Adicionar Item',
            })
            steps.push({
                op: 'click',
                action: 'abrir-modal-adicionar',
                label: `Abrir modal (produto ${i + 1}/${entities.produtos.length})`,
                expects: { modal_opens: 'modal-adicionar' },
            })
        }
        steps.push({
            op: 'type',
            field: 'produto',
            value: produto.nome,
            label: `Produto: ${produto.nome}`,
        })
        steps.push({
            op: 'type',
            field: 'quantidade',
            value: String(produto.quantidade),
            label: `Quantidade: ${produto.quantidade}`,
        })
        steps.push({
            op: 'click',
            action: 'adicionar-produto',
            label: `Lançar ${produto.nome}`,
            expects: { modal_closes: 'modal-adicionar' },
        })
        if (i < entities.produtos.length - 1) {
            steps.push({ op: 'pause', ms: 400, label: 'Aguardar próximo' })
        }
    }

    return steps
}

export const lancarProducaoDiaria: SkillModule<typeof Input> = {
    id: 'lancar_producao_diaria',
    route: '/producao-diaria',
    description: 'Lançar produção diária na loja: lista de produtos com quantidades. Cada produto vira uma entry em daily_production_products.',
    triggerHints: ['lançar produção', 'produção do dia', 'produzi', 'produção diária', 'registrar produção', 'fazer produção'],
    input: Input,
    detectAmbiguities,
    build,
}

