  try {
    await withTrace('producao.diaria.registrar', async () => {
      // Find distinct product names
      const uniqueProductNames = Array.from(new Set(productionEntries.map(e => e.product_name.trim().toLowerCase())));

      // Fetch matching master products
      const masterMap: Record<string, number> = {};
      if (uniqueProductNames.length > 0) {
        const { data: masters, error: mError } = await supabase
          .from('produtos_master')
          .select('id, nome')
          .filter('ativo', 'eq', true); // or just get everything since it is an exact match lookup

        if (!mError && masters) {
          // Fallback similarity matching
          masters.forEach(m => {
            if (m.nome) {
              const cleanMasterName = m.nome.trim().toLowerCase();
              masterMap[cleanMasterName] = m.id;
            }
          });
        }
      }

      const payload = productionEntries.map(entry => {
        const cleanEntryName = entry.product_name.trim().toLowerCase();

        // Exact match
        let matchedId = masterMap[cleanEntryName] || null;

        // Very basic fuzzy fallback just in case
        if (!matchedId) {
          const possibleKeys = Object.keys(masterMap);
          for (const k of possibleKeys) {
            if (k.includes(cleanEntryName) || cleanEntryName.includes(k)) {
              matchedId = masterMap[k];
              break;
            }
          }
        }

        return {
          date: selectedDate,
          product_name: entry.product_name,
          quantity: entry.quantity,
          produto_master_id: matchedId,
          created_by: user.id,
        };
      });

      const { error } = await supabase
        .from('daily_production')
        .insert(payload);

      if (error) throw error;
    }, telemetryAttrs);

    const durationMs = Math.round(performance.now() - startTime);
    const totalQuantity = productionEntries.reduce((sum, e) => sum + e.quantity, 0);

    wideInfo('producao.diaria.registrada', 'Produção diária registrada com sucesso', {
      attributes: {
        'producao.quantidade_produtos': productionEntries.length,
        'producao.quantidade_total': totalQuantity,
        'producao.data': selectedDate,
        'duration_ms': durationMs,
      },
    });
    recordProductionRecord({ 'producao.data': selectedDate });
    recordOperationDuration('producao.diaria', durationMs);

    toast({
      title: "Produção registrada com sucesso!",
      description: `${productionEntries.length} produtos salvos para ${formatDateBR(selectedDate)}`,
      duration: 3000
    });

    // Limpar formulário
    setProductionEntries([]);
    setSearchTerm("");
    setIsDateModalOpen(false);

  } catch (error) {
    const durationMs = Math.round(performance.now() - startTime);
    wideError('producao.diaria.erro', 'Falha ao registrar produção diária', {
      attributes: {
        'error.message': error instanceof Error ? error.message : String(error),
        'duration_ms': durationMs,
      },
    });
    recordError('producao_diaria', 'registrar');
    handleError(error, { domain: 'producao', operation: 'registerProduction', showToast: false });
    toast({ title: 'Erro ao registrar produção', variant: 'destructive' });
  } finally {
    setIsLoading(false);
  }
};

