  const reloadDailyList = async () => {
    const { data: additionsData, error: additionsError } = await supabase
      .from('daily_production_products')
      .select('id, name, active');
    if (additionsError) {
      handleError(additionsError, { domain: 'producao', operation: 'loadDailyProductionProducts', showToast: false });
      setDailyAdditions([]);
    } else {
      setDailyAdditions(additionsData || []);
    }

    const { data: exclusionsData, error: exclusionsError } = await supabase
      .from('daily_production_exclusions')
      .select('name');
    if (exclusionsError) {
      handleError(exclusionsError, { domain: 'producao', operation: 'loadDailyProductionExclusions', showToast: false });
      setDailyExclusions([]);
    } else {
      setDailyExclusions((exclusionsData || []).map((e: any) => e.name));
    }

    const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
    const activeAdditions = (additionsData || []).filter((a: any) => a.active).map((a: any) => a.name);
    const includedDefaults = DAILY_PRODUCTION_PRODUCTS.filter(p => !exclusions.includes(p.toLowerCase()));
    const finalList = Array.from(new Set([...activeAdditions, ...includedDefaults]));
    setAllProducts(finalList);
  };

  reloadDailyList();
}, []);

// Funções para entrada de produção
const openAddModal = (productName?: string) => {
  setSelectedProduct(productName || "");
  setNewQuantity("");
  setIsAddModalOpen(true);
};

const closeAddModal = () => {
  setIsAddModalOpen(false);
  setSelectedProduct("");
  setNewQuantity("");
};

// Importação via WhatsApp (IA)
const openImportModal = async () => {
  setWhatsappMessage("");
  setAiItems([]);
  setMatchedItems([]);
  setIsImportModalOpen(true);
  // Importação via WhatsApp: usar padrões incluídos + adicionados ativos
  try {
    const { data: additionsData } = await supabase
      .from('daily_production_products')
      .select('id, name, active');

    const { data: exclusionsData } = await supabase
      .from('daily_production_exclusions')
      .select('name');

    const exclusions = (exclusionsData || []).map((e: any) => (e.name || '').toLowerCase());
    const defaultsIncluded = DAILY_PRODUCTION_PRODUCTS
      .filter(p => !exclusions.includes(p.toLowerCase()))
      .map((product, index) => ({ id: -(index + 1), nome: product }));

    const activeAdditions = (additionsData || [])
      .filter((a: any) => a.active)
      .map((a: any) => ({ id: a.id, nome: a.name }));

    setDbProducts([...activeAdditions, ...defaultsIncluded]);
  } catch (err) {
    handleError(err, { domain: 'producao', operation: 'buildAiProductList', showToast: false });
    const constantProducts = DAILY_PRODUCTION_PRODUCTS.map((product, index) => ({ id: -(index + 1), nome: product }));
    setDbProducts(constantProducts);
  }
};

// Estado para texto intermediário (enquanto fala)
const [interimText, setInterimText] = useState("");
const [voiceStatus, setVoiceStatus] = useState<string>("");

